<template>
	<div
		class="min-h-dvh bg-ui-canvas"
		style="padding-bottom: calc(2rem + env(safe-area-inset-bottom))"
	>
		<!-- HEADER (bar putih full-width) -->
		<header
			class="bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="app-container">
				<div class="flex items-center gap-2">
					<button
						type="button"
						@click="goBack"
						class="-ml-2 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
						aria-label="Kembali"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="w-7 h-7"
							fill="none"
							stroke="currentColor"
							stroke-width="2.2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="m12 19-7-7 7-7" />
							<path d="M19 12H5" />
						</svg>
					</button>
					<h1 class="text-xl font-semibold text-ui-heading">Dashboard</h1>
				</div>
				<!-- <p class="mt-2 text-base font-medium text-ui-ink-slate-400">
					Pilih dashboard yang ingin Anda lihat
				</p> -->
			</div>
		</header>

		<!-- PILIHAN — pilihan berbeda per role (CMO vs Pimcab). Tiap opsi mengarah
		     ke Frappe desk page (/app/<page-name>) → navigasi penuh (keluar SPA). -->
		<main class="app-container card-grid px-5 pt-6">
			<!-- Tunggu role selesai dimuat agar pilihan dashboard tidak salah role -->
			<div v-if="!ready" class="flex justify-center pt-6">
				<svg
					class="w-6 h-6 text-primary animate-spin"
					viewBox="0 0 24 24"
					fill="none"
					xmlns="http://www.w3.org/2000/svg"
				>
					<circle
						cx="12"
						cy="12"
						r="9"
						stroke="currentColor"
						stroke-width="2"
						stroke-opacity="0.25"
					/>
					<path
						d="M21 12a9 9 0 0 0-9-9"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
					/>
				</svg>
			</div>

			<component
				:is="opt.route ? RouterLink : opt.href ? 'a' : 'div'"
				v-for="opt in options"
				:key="opt.key"
				:to="opt.route || undefined"
				:href="opt.route ? undefined : opt.href || undefined"
				@click="opt.href && !opt.route ? onDeskLink($event, opt.href) : undefined"
				class="w-full bg-ui-surface rounded-[1.75rem] px-6 py-6 flex items-center gap-4 shadow-sm active:bg-ui-surface-gray-50"
			>
				<span class="shrink-0 text-primary">
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="w-9 h-9"
						fill="none"
						stroke="currentColor"
						stroke-width="1.8"
						stroke-linecap="round"
						stroke-linejoin="round"
						v-html="opt.icon"
					/>
				</span>
				<span
					class="flex-1 min-w-0 text-left text-base font-semibold text-ui-heading leading-snug"
				>
					{{ opt.title }}
				</span>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="w-6 h-6 text-primary shrink-0"
					fill="none"
					stroke="currentColor"
					stroke-width="2.2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="m9 18 6-6-6-6" />
				</svg>
			</component>
		</main>
	</div>
</template>

<script setup>
import { computed } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import { useRoleMenu } from '../composables/useRoleMenu'
import { isNativeApp, openInAppBrowser } from '../data/mobile'
import { notifyError } from '../composables/toast'
import { currentUser } from '../data/user'

const router = useRouter()
const { ready, roles, department } = useRoleMenu()

// Membuka halaman Frappe Desk (mis. /app/cmo-sales-dashboard).
//
// Di WEB: biarkan <a href> menavigasi normal (same-origin, sesi cookie ada).
// Di NATIVE: app berjalan dari bundel lokal (origin https://localhost) & memakai
// token, bukan cookie — navigasi langsung ke /app menghasilkan LAYAR PUTIH.
// Maka: minta URL login sekali-pakai (menukar token -> sesi cookie di server)
// lalu buka di in-app browser sehingga Desk tampil dengan sesi yang benar.
const deskTokenRes = createResource({
	url: 'juragan.api.portal.desk_bridge.create_desk_login_token',
	method: 'POST',
})

async function onDeskLink(e, href) {
	if (!isNativeApp()) return // web: biarkan navigasi <a> normal
	e.preventDefault()
	try {
		const res = await deskTokenRes.submit({ redirect: href })
		await openInAppBrowser(res.url)
	} catch (err) {
		notifyError(err, 'Gagal membuka dashboard')
	}
}
const hasCollRole = computed(() => roles.value.some((r) => /coll/i.test(r)))

// Chooser dipakai CMO & Pimcab — yang membedakan hanya pilihan dashboard-nya.
// Semua mengarah ke Frappe desk Page (/app/<page-name>), navigasi penuh (keluar SPA).
const CMO_OPTIONS = [
	{
		key: 'cmo-sales-dashboard',
		title: 'CMO Sales Dashboard',
		desc: 'Dashboard penjualan CMO',
		href: '/app/cmo-sales-dashboard',
		icon: '<rect width="7" height="9" x="3" y="3" rx="1"/><rect width="7" height="5" x="14" y="3" rx="1"/><rect width="7" height="9" x="14" y="12" rx="1"/><rect width="7" height="5" x="3" y="16" rx="1"/>',
	},
	{
		key: 'cmo-dashboard-fid-fpd',
		title: 'CMO Dashboard FID/FPD',
		desc: 'Dashboard FID & FPD CMO',
		href: '/app/cmo-dashboard-fid-fpd',
		icon: '<path d="M3 3v16a2 2 0 0 0 2 2h16"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/>',
	},
]
// Opsi dashboard umum (dipakai Pimcab & Director).
const SALES_DASHBOARD = {
	key: 'sales-dashboard-juragan',
	title: 'Sales Dashboard',
	desc: 'Lihat dashboard sales',
	href: '/app/sales-dashboard-juragan',
	icon: '<line x1="12" y1="20" x2="12" y2="10"/><line x1="18" y1="20" x2="18" y2="4"/><line x1="6" y1="20" x2="6" y2="16"/>',
}
const FID_FPD_DASHBOARD = {
	key: 'fid-fpd-dashboard',
	title: 'Fid Fpd Dashboard',
	desc: 'Lihat dashboard FID / FPD',
	href: '/app/fid-fpd-dashboard',
	icon: '<path d="M3 3v16a2 2 0 0 0 2 2h16"/><path d="m19 9-5 5-4-4-3 3"/>',
}
const COLLECTOR_DASHBOARD = {
	key: 'collector',
	title: 'List Collector',
	desc: 'Daftar Collector',
	href: '/app/collector',
	icon: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
}
const REALISASI_COLLECTION = {
	key: 'realisasi-collection',
	title: 'Realisasi Collection',
	desc: 'Realisasi penagihan Collection',
	href: '/app/realisasi-collection',
	icon: '<path d="M3 3v16a2 2 0 0 0 2 2h16"/><path d="m19 9-5 5-4-4-3 3"/>',
}
const DASHBOARD_STOK_UNIT = {
	key: 'dashboard-stok-unit',
	title: 'Dashboard Stok Unit',
	desc: 'Stok unit motor',
	icon: '<path d="M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z"/><path d="m3.3 7 8.7 5 8.7-5"/><path d="M12 22V12"/>',
	href: '/app/dashboard-stok-unit',
}
const VISIT_COLLECTION_DASHBOARD = {
	key: 'monitoring-kunjungan',
	title: 'Monitoring Kunjungan Field Coll',
	desc: 'Kunjungan dan hasil aktivitas harian',
	route: { name: 'MonitoringKunjungan' },
	icon: '<rect width="7" height="9" x="3" y="3" rx="1"/><rect width="7" height="5" x="14" y="3" rx="1"/><rect width="7" height="9" x="14" y="12" rx="1"/><rect width="7" height="5" x="3" y="16" rx="1"/>',
}
const MY_VISIT_COLLECTION_DASHBOARD = {
	...VISIT_COLLECTION_DASHBOARD,
	key: 'monitoring-kunjungan-saya',
	title: 'Monitoring Kunjungan Field Collection',
	desc: 'Kunjungan dan hasil aktivitas Field Collection',
	route: { name: 'MonitoringKunjunganSaya' },
}
const LEGACY_FIELD_COLL_DASHBOARD = {
	key: 'field-coll-dashboard',
	title: 'Field Coll Dashboard',
	desc: 'Dashboard Field Collection lama',
	href: '/app/field-coll-dashboard',
	icon: VISIT_COLLECTION_DASHBOARD.icon,
}

// Pimcab / Pimpinan Cabang → Sales Dashboard + Fid Fpd Dashboard.
const PIMCAB_OPTIONS = [SALES_DASHBOARD, FID_FPD_DASHBOARD]

// Director tetap memiliki dashboard lama dan bisa membuka monitoring Portal.
const DIRECTOR_OPTIONS = [
	SALES_DASHBOARD,
	FID_FPD_DASHBOARD,
	COLLECTOR_DASHBOARD,
	LEGACY_FIELD_COLL_DASHBOARD,
	VISIT_COLLECTION_DASHBOARD,
]

// Owner → Sales Dashboard, Fid Fpd Dashboard, List Collector, Realisasi
// Collection, Dashboard Stok Unit. Semua desk page-nya sudah ada; role 'Owner'
// sendiri belum ada di database (lihat MENU_OWNER di Home.vue).
const OWNER_OPTIONS = [
	SALES_DASHBOARD,
	FID_FPD_DASHBOARD,
	COLLECTOR_DASHBOARD,
	REALISASI_COLLECTION,
	DASHBOARD_STOK_UNIT,
]

// Alur kerja dan dashboard Collection baru memakai route Portal.
const FIELD_COLL_OPTIONS = [
	MY_VISIT_COLLECTION_DASHBOARD,
	{
		key: 'pekerjaan-saya',
		title: 'Pekerjaan Saya',
		desc: 'Rekomendasi kunjungan hari ini',
		route: { name: 'PekerjaanSaya' },
		// Ikon dashboard/grid (ikon orang2 dipindah ke List Collector).
		icon: '<rect width="7" height="9" x="3" y="3" rx="1"/><rect width="7" height="5" x="14" y="3" rx="1"/><rect width="7" height="9" x="14" y="12" rx="1"/><rect width="7" height="5" x="3" y="16" rx="1"/>',
	},
	{
		key: 'list-collector',
		title: 'List Collector',
		desc: 'Daftar Collector',
		href: '/app/collector',
		// Ikon orang2 (users) — sebelumnya dipakai Field Coll Dashboard.
		icon: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
	},
]
const SUPERVISOR_COLL_OPTIONS = [VISIT_COLLECTION_DASHBOARD, FIELD_COLL_OPTIONS[2]]
const LEGACY_COLL_OPTIONS = [LEGACY_FIELD_COLL_DASHBOARD, FIELD_COLL_OPTIONS[2]]

// Prioritas: Owner → 5 dashboard; Director → 4 dashboard; Pimcab/Pimpinan
// Cabang → 2 dashboard; role *Coll* → Field Coll; selain itu (CMO/Marketing) →
// dashboard CMO.
const options = computed(() => {
	const r = roles.value
	if (currentUser.user === 'Administrator') return [...DIRECTOR_OPTIONS, MY_VISIT_COLLECTION_DASHBOARD]
	let choices
	if (r.includes('Owner')) choices = r.includes('Director') ? [...OWNER_OPTIONS, VISIT_COLLECTION_DASHBOARD] : OWNER_OPTIONS
	else if (r.includes('Director')) choices = DIRECTOR_OPTIONS
	else if (r.includes('Pimcab') || r.includes('Pimpinan Cabang') || department.value?.key === 'pimcab') choices = PIMCAB_OPTIONS
	else if (r.includes('Head Field Coll') || r.includes('Manager Coll')) choices = SUPERVISOR_COLL_OPTIONS
	else if (r.includes('Field Coll')) choices = FIELD_COLL_OPTIONS
	else if (hasCollRole.value) choices = LEGACY_COLL_OPTIONS
	else choices = CMO_OPTIONS
	return r.includes('Field Coll') && !choices.includes(MY_VISIT_COLLECTION_DASHBOARD)
		? [...choices, MY_VISIT_COLLECTION_DASHBOARD]
		: choices
})

function goBack() {
	router.push({ name: 'Home' })
}
</script>
